const filas=$input.all().map(item=>item.json);
if(!filas.length)throw new Error('La consulta no devolvio filas para el piloto.');
const series=new Set(filas.map(r=>`${r.id_sucursal}|${r.id_articulo}`));
const sucursales=new Set(filas.map(r=>String(r.id_sucursal)));
const rubros=new Set(filas.map(r=>String(r.rubro||'sin_clasificar')));
const subrubros=new Set(filas.map(r=>String(r.subrubro||'sin_clasificar')));
const gruposArticulo=new Set(filas.map(r=>String(r.grupo_articulo||'sin_clasificar')));
const colores=new Set(filas.map(r=>String(r.color||'sin_clasificar')));
const talles=new Set(filas.map(r=>String(r.talle||'sin_clasificar')));
const regulares=new Set(filas.filter(r=>r.patron_muestra==='regular').map(r=>`${r.id_sucursal}|${r.id_articulo}`));
const intermitentes=new Set(filas.filter(r=>r.patron_muestra==='intermitente').map(r=>`${r.id_sucursal}|${r.id_articulo}`));
const fechas=filas.map(r=>String(r.fecha_comprobante)).sort();
return [{json:{
  estado:'DATASET_PILOTO_OK',
  solo_lectura:true,
  criterio_muestra:'hasta 20 series por sucursal y patron, priorizando diversidad de rubros',
  filas_semanales:filas.length,
  series_articulo_sucursal:series.size,
  sucursales:sucursales.size,
  rubros:rubros.size,
  subrubros:subrubros.size,
  grupos_articulo:gruposArticulo.size,
  colores:colores.size,
  talles:talles.size,
  series_regulares:regulares.size,
  series_intermitentes:intermitentes.size,
  fecha_minima:fechas[0],
  fecha_maxima:fechas[fechas.length-1],
  nodo_datos:'Postgres - Ventas semanales piloto',
  siguiente_paso:'Procesar la salida del nodo de datos con el motor Python local.'
}}];
